import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        String s = next();
        int[] remaining = new int[26];
        for (int i = 0; i < s.length(); i++) remaining[s.charAt(i) - 'A']++;
        // letters with odd frequency keep exactly one copy; the rest vanish
        boolean[] required = new boolean[26], used = new boolean[26];
        for (int c = 0; c < 26; c++) required[c] = remaining[c] % 2 == 1;
        StringBuilder stack = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            int c = ch - 'A';
            remaining[c]--;
            if (!required[c] || used[c]) continue;
            // pop larger letters that still appear later
            while (stack.length() > 0) {
                char top = stack.charAt(stack.length() - 1);
                if (top <= ch || remaining[top - 'A'] == 0) break;
                used[top - 'A'] = false;
                stack.setLength(stack.length() - 1);
            }
            stack.append(ch);
            used[c] = true;
        }
        System.out.println(stack);
    }
}

