	var remaining [26]int
	for i := 0; i < len(s); i++ {
		remaining[s[i]-'A']++
	}
	// letters with odd frequency keep exactly one copy; the rest vanish
	var required, used [26]bool
	for c := range required {
		required[c] = remaining[c]%2 == 1
	}
	var stack []byte
	for i := 0; i < len(s); i++ {
		ch := s[i]
		c := ch - 'A'
		remaining[c]--
		if !required[c] || used[c] {
			continue
		}
		// pop larger letters that still appear later
		for len(stack) > 0 && stack[len(stack)-1] > ch && remaining[stack[len(stack)-1]-'A'] > 0 {
			used[stack[len(stack)-1]-'A'] = false
